(4009999, 570676, 30490, '<td valign="top">A little too much brown in this photo.  Maybe a different colored background might have offset your subjects better and highlighted the coffee beans.</td>', 'A little too much brown in this photo.  Maybe a different colored background might have offset your subjects better and highlighted the coffee beans.', '2007-08-18 22:35:33.000000', NULL, 1),
(4010002, 570190, 30490, '<td valign="top">Healthy yes, but it just doesn''t say "fast food" to me...</td>', 'Healthy yes, but it just doesn''t say "fast food" to me...', '2007-08-18 22:37:02.000000', NULL, 1),
(4010004, 569437, 30490, '<td valign="top">This composition is just a jumble and too washed out with harsh lighting.  A bit more negative space would improve the shot and softer lighting.</td>', 'This composition is just a jumble and too washed out with harsh lighting.  A bit more negative space would improve the shot and softer lighting.', '2007-08-18 22:38:02.000000', NULL, 1),
(4010007, 569534, 30490, '<td valign="top">OK it is a fast food restaurant, but it just isn''t working for me...</td>', 'OK it is a fast food restaurant, but it just isn''t working for me...', '2007-08-18 22:39:00.000000', NULL, 1),
