(4010009, 570378, 30490, '<td valign="top">The partially eaten meal is really unapealing</td>', 'The partially eaten meal is really unapealing', '2007-08-18 22:39:58.000000', NULL, 1),
(4010011, 569200, 30490, '<td valign="top">The lighting is too harsh and I think the photo might be too tightly cropped.</td>', 'The lighting is too harsh and I think the photo might be too tightly cropped.', '2007-08-18 22:41:38.000000', NULL, 1),
(4010013, 570656, 30490, '<td valign="top">Great idea, just a little blown out...</td>', 'Great idea, just a little blown out...', '2007-08-18 22:43:08.000000', NULL, 1),
(4010015, 570329, 30490, '<td valign="top">Love the skin tone, this one made me think.  I get the connection to the challenge, but I am guessing some voters may not...</td>', 'Love the skin tone, this one made me think.  I get the connection to the challenge, but I am guessing some voters may not...', '2007-08-18 22:43:55.000000', NULL, 1),
